#容斥

就是一个简单的容斥，只要记录x,y有多少行和列被扫到就好

行被扫到*列数+列被扫到*行数-重合；

其实数据还可以再大的。。

PS：数据如果再大就要用线段树了

#include<iostream>
#include<cstdio>
#include<cstdlib>
using namespace std;
int N,M,B,G,ans1,ans2;
int x,y;
bool X[5003],Y[5003];
int main(){
    cin>>N>>M>>B>>G;
    for(int i=1;i<=B;i++){
     cin>>x>>y;
     for(int i=x;i<=y;i++)Y[i]=1;
    }
    for(int i=1;i<=G;i++){
     cin>>x>>y;
     for(int i=x;i<=y;i++)X[i]=1;
    }
    for(int i=1;i<=N;i++)
     if(Y[i])ans1++;
    for(int i=1;i<=M;i++)
     if(X[i])ans2++;
    cout<<ans1*M+ans2*N-ans1*ans2;
}
